cat > tests/findings.rs <<'EOF'
mod common;
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::sync::Arc;
use credentials_backend::notifier::*;
use credentials_backend::resolver::*;
use credentials_backend::settings::*;
use credentials_backend::status::*;
use credentials_backend::transport::*;
use credentials_backend::verifier::*;
use credentials_backend::webhook::*;
use serde_json::json;
use common::*;

/// Serves Harbour's document, or nothing while `down` is set; counts GETs.
struct Flaky { down: AtomicBool, gets: AtomicUsize }
impl DocumentTransport for Flaky {
    fn get(&self, url: &str) -> Result<Vec<u8>, TransportError> {
        self.gets.fetch_add(1, Ordering::SeqCst);
        if self.down.load(Ordering::SeqCst) { return Err(TransportError::Io { url: url.into(), reason: "timeout".into() }); }
        transport().get(url)
    }
}

#[test]
fn b1_last_index_of_a_status_list() {
    let store = store();
    let list = harbour().status_list();
    for _ in 0..(DEFAULT_CAPACITY - 1) { store.allocate_status_index(&list).unwrap(); }
    let holder = Holder::new(1);
    let issued = harbour().issue(&store, &membership_request(&holder)).unwrap();
    let id = issued.credential["id"].as_str().unwrap();
    println!("B1 index={} capacity={}", issued.credential["credentialStatus"]["statusListIndex"], DEFAULT_CAPACITY);
    println!("B1 revoke -> {:?}", revoke_credential(&store, id).map(|c| c.revoked));
    println!("B1 is_revoked after revoke -> {:?}", store.is_revoked(&list, DEFAULT_CAPACITY));
    let vp = holder.present(&issued, &["member"], NONCE, DOMAIN);
    println!("B1 door -> {:?}", verifier(store).verify_presentation(&submission("r", vp), NONCE, DOMAIN).map(|v| v.holder));
}

#[test]
fn b2_failed_attempt_consumes_the_upload_id() {
    let store = store();
    let t = Arc::new(Flaky { down: AtomicBool::new(true), gets: AtomicUsize::new(0) });
    let v = Verifier::new(Resolver::new(t.clone()), store.clone()).with_clock(|| NOW);
    let holder = Holder::new(1);
    let issued = harbour().issue(&store, &membership_request(&holder)).unwrap();
    let vp = holder.present(&issued, &["member"], NONCE, DOMAIN);
    println!("B2 first try (issuer doc unreachable) -> {:?}", v.verify_presentation(&submission("upload-1", vp.clone()), NONCE, DOMAIN).err().map(|e| e.to_string()));
    t.down.store(false, Ordering::SeqCst);
    println!("B2 retry same upload (doc back) -> {:?}", v.verify_presentation(&submission("upload-1", vp), NONCE, DOMAIN).map(|p| p.holder).map_err(|e| e.to_string()));
}

#[test]
fn b3_every_scan_fetches_the_issuer_document() {
    let store = store();
    let t = Arc::new(Flaky { down: AtomicBool::new(false), gets: AtomicUsize::new(0) });
    let v = Verifier::new(Resolver::new(t.clone()), store.clone()).with_clock(|| NOW);
    let issued = harbour().issue(&store, &membership_request(&Holder::new(1))).unwrap();
    for _ in 0..3 { v.verify_credential(&issued.credential).unwrap(); }
    println!("B3 GETs for 3 verifications of one issuer: {}", t.gets.load(Ordering::SeqCst));
}

#[tokio::test(start_paused = true)]
async fn b4_malformed_subscription_leaves_no_record() {
    let settings = Arc::new(SettingsStore::new());
    let t = Arc::new(HermeticTransport::new());
    let sink = Arc::new(MemorySink::default());
    let n = Notifier::new(settings.clone(), t.clone(), sink.clone());
    let tenant = HARBOUR_DID;
    settings.put(Setting::new(tenant, "webhook/good", WEBHOOK_KIND, json!({ "url": "https://good.rp.example/h" })));
    t.route("https://good.rp.example/h", Endpoint::ok());
    settings.put(Setting::new(tenant, "webhook/typo", WEBHOOK_KIND, json!({ "uri": "https://typo.rp.example/h" })));
    settings.put(Setting::new(tenant, "webhook/number", WEBHOOK_KIND, json!({ "url": 42 })));
    n.notify(&StatusChange { credential_id: "c".into(), issuer: tenant.into(), status_list: "l".into(), status_index: 1, revoked: true }).await;
    let ids: Vec<String> = sink.events().into_iter().map(|e| e.subscription).collect();
    println!("B4 webhook settings: 3 (good, typo, number); recorded outcomes for: {ids:?}");
}

#[tokio::test(start_paused = true)]
async fn b5_health_flag_shared_across_concurrent_changes() {
    let settings = Arc::new(SettingsStore::new());
    let t = Arc::new(HermeticTransport::new());
    let sink = Arc::new(MemorySink::default());
    let n = Notifier::new(settings.clone(), t.clone(), sink.clone());
    let big = "did:web:big.example";
    t.route_host("never.rp.example", Endpoint::ok());
    for i in 0..17_000 { settings.put(Setting::new(big, &format!("webhook/{i:05}"), WEBHOOK_KIND, json!({ "url": format!("https://never.rp.example/{i}") }))); }
    let change = |tenant: &str| StatusChange { credential_id: format!("c-{tenant}"), issuer: tenant.into(), status_list: "l".into(), status_index: 1, revoked: true };
    tokio::join!(n.notify(&change(HARBOUR_DID)), n.notify(&change(big)));
    let canary: Vec<_> = sink.events().into_iter().filter(|e| e.subscription == CANARY_ID).map(|e| (e.tenant, e.outcome)).collect();
    println!("B5 canary outcomes: {canary:?}");
    println!("B5 canary_healthy after both: {}", n.canary_healthy());
}

#[test]
fn b6_issuance_to_a_holder_the_door_cannot_resolve() {
    let short = affinidi_encoding::encode_multikey(affinidi_encoding::ED25519_PUB, &[1u8; 31]);
    let mut request = membership_request(&Holder::new(1));
    request.holder = format!("did:key:{short}");
    println!("B6 issue -> {:?}", harbour().issue(&store(), &request).map(|i| i.credential["credentialSubject"]["id"].clone()));
    println!("B6 door resolves that holder -> {:?}", Resolver::new(Arc::new(transport())).resolve(&request.holder).err().map(|e| e.to_string()));
}

#[test]
fn b7_did_web_with_an_ip_address() {
    println!("B7 {:?}", did_web_url("did:web:10.0.0.5"));
}
EOF
cargo test --offline --test findings -- --nocapture --test-threads=1 2>&1 | grep -oE "B[0-9] .*|error.*|panicked.*"

