import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';
import 'package:credentials_app/src/credential_store.dart';
import 'package:credentials_app/src/held_credential.dart';
import 'package:credentials_app/src/holder_key.dart';
import 'package:credentials_app/src/issuer_client.dart';
import 'package:credentials_app/src/presentation_request.dart';
import 'package:credentials_app/src/wallet_service.dart';

class NoIssuer implements IssuerClient {
  @override
  Future<HeldCredential> issue({required String holderDid, required String credentialType}) => throw UnimplementedError();
}

PresentationRequest req(String nonce) => PresentationRequest.fromJson({
  'client_id': 'door.harbourclub.example', 'nonce': nonce,
  'dcql_query': {'credentials': [{'id': 'm', 'format': 'ldp_vc', 'claims': [{'path': ['credentialSubject', 'member']}]}]},
});

Future<void> main(List<String> args) async {
  final issuance = jsonDecode(File(args[0]).readAsStringSync()) as Map<String, dynamic>;
  final id = issuance['credential']['id'] as String;
  final seed = Uint8List.fromList(List.filled(32, 7));
  final at = () => DateTime.fromMillisecondsSinceEpoch(1780272000 * 1000, isUtc: true);

  // W1: the returned presentation shares the held credential's map.
  final wallet = WalletService(issuer: NoIssuer(), store: CredentialStore()..save(HeldCredential.fromIssuance(issuance)),
      newKey: () => HolderKey.fromSeed(seed), now: at);
  final first = await wallet.createPresentation(id, req('first'));
  print('W1 same object: ${identical(first['verifiableCredential'], wallet.credential(id)!.vc)}');
  (first['verifiableCredential'] as Map<String, dynamic>)['displayName'] = 'Harbour Club';   // a caller annotating the answer
  print('W1 held credential now has displayName: ${wallet.credential(id)!.vc.containsKey('displayName')}');
  final second = await wallet.createPresentation(id, req('second'));
  File(args[1]).writeAsStringSync(jsonEncode(second));
  print('W1 next presentation written for the backend check');

  // W2: a store holding the credential but no holder key yet.
  final keyless = WalletService(issuer: NoIssuer(), store: CredentialStore()..save(HeldCredential.fromIssuance(issuance)), now: at);
  final vp = await keyless.createPresentation(id, req('third'));
  print('W2 subject=${issuance['credential']['credentialSubject']['id']}');
  print('W2 holder =${vp['holder']}');
  File(args[2]).writeAsStringSync(jsonEncode(vp));
}
EOF
